import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { chmodSync, mkdirSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { recordedInvocations, registrations, type Registration } from "../src/execute";
import { createFixture, sentinelLauncher, type Fixture } from "../src/fixture";
import { writeRecordingWrapper } from "../src/live";
import { cleanupOwnedProcesses, run, SYSTEM_PATH } from "../src/process";

// Executes the settings and hook scripts generated by the real `sentinel integrate claude-code
// --guard-approved-specs`, launched the way Claude Code 2.1.292 launches command hooks
// (https://code.claude.com/docs/en/hooks): in the session's current directory, with
// CLAUDE_PROJECT_DIR set; a handler with `args` is exec'd with ${CLAUDE_PROJECT_DIR} substituted,
// otherwise the command runs through the shell. The real Sentinel answers behind a recording
// wrapper, so responses follow Sentinel's actual protocol mapping.

let fixture: Fixture;
let settings: any;
let log: string;
let bin: string;
let session = 0;

beforeAll(async () => {
  const sentinel = sentinelLauncher(process.env)!;
  fixture = await createFixture({ harness: "claude-code", guard: true, sentinel, gates: ["format", "checkstyle"] });
  settings = JSON.parse(readFileSync(join(fixture.root, ".claude/settings.json"), "utf8"));
  bin = join(dirname(fixture.root), "sentinel-bin");
  log = join(dirname(fixture.root), "sentinel-log");
  writeRecordingWrapper(bin, log, sentinel);
  mkdirSync(join(fixture.root, "src/main/java"), { recursive: true });
  mkdirSync(join(fixture.root, "openspec/specs/auth"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/specs/auth/spec.md"), "# Auth\n");
  mkdirSync(join(fixture.root, "openspec/changes/add-x"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/changes/add-x/tasks.md"), "- [ ] 1.1\n");
  // A trusted stand-in OpenSpec validation: it reports a finding while SPEC_FAIL exists.
  writeFileSync(
    join(fixture.root, "openspec-stub.sh"),
    '#!/bin/sh\nif [ -f SPEC_FAIL ]; then echo "add-x: missing scenario"; exit 1; fi\necho ok\n',
  );
  chmodSync(join(fixture.root, "openspec-stub.sh"), 0o755);
  writeFileSync(
    join(fixture.root, "sentinel.toml"),
    `${readFileSync(join(fixture.root, "sentinel.toml"), "utf8")}\n[quality-gates.openspec]\nenabled = true\ncommand = ["./openspec-stub.sh"]\n`,
  );
});

afterAll(() => {
  fixture?.cleanup();
  cleanupOwnedProcesses();
});

function handlers(event: string): (Registration & { args?: string[] })[] {
  const groups = settings.hooks?.[event] ?? [];
  const found = registrations(JSON.stringify({ hooks: { [event]: groups } }), "matcher-groups");
  // Re-attach exec-form arguments, which the shared parser does not model.
  return found.map((registration, index) => {
    const handler = groups.flatMap((group: any) => group.hooks)[index];
    return Array.isArray(handler?.args) ? { ...registration, args: handler.args } : registration;
  });
}

const matches = (registration: Registration, tool: string) =>
  registration.matcher === undefined || new RegExp(registration.matcher).test(tool);

/** Launches one handler like Claude Code, from `cwd`, with the event on stdin. */
async function launch(registration: Registration & { args?: string[] }, payload: unknown, cwd: string) {
  const before = recordedInvocations(log).length;
  const env = { ...fixture.env, PATH: `${bin}:${SYSTEM_PATH}`, CLAUDE_PROJECT_DIR: fixture.root };
  const stdin = typeof payload === "string" ? payload : JSON.stringify(payload);
  const argv = registration.args
    ? [registration.command.replaceAll("${CLAUDE_PROJECT_DIR}", fixture.root), ...registration.args]
    : ["/bin/sh", "-c", registration.command];
  const result = await run(argv, { cwd, env, stdin, timeoutMs: 60_000 });
  return { result, invocations: recordedInvocations(log).slice(before) };
}

function payload(event: string, extra: Record<string, unknown> = {}) {
  return { session_id: `s${session++}`, cwd: fixture.root, hook_event_name: event, permission_mode: "default", ...extra };
}

describe("generated settings", () => {
  test("register each Sentinel hook once in the documented matcher-group shape", () => {
    expect(handlers("PostToolUse").length).toBe(1);
    expect(handlers("Stop").length).toBe(1);
    expect(handlers("PreToolUse").length).toBe(1);
  });

  test("matchers select the edit tools after a call and the guarded tools before one", () => {
    const [post] = handlers("PostToolUse");
    expect(["Edit", "Write", "MultiEdit"].every((tool) => matches(post, tool))).toBe(true);
    expect(["Read", "Bash", "NotebookEdit", "EditOther"].some((tool) => matches(post, tool))).toBe(false);
    const [pre] = handlers("PreToolUse");
    expect(["Edit", "Write", "MultiEdit", "NotebookEdit", "Bash", "Skill"].every((tool) => matches(pre, tool))).toBe(true);
    expect(matches(pre, "Read")).toBe(false);
  });

  test("hook commands are anchored at the project directory", () => {
    for (const event of ["PostToolUse", "Stop", "PreToolUse"]) {
      for (const handler of handlers(event)) expect(handler.command.startsWith("${CLAUDE_PROJECT_DIR}/.claude/hooks/")).toBe(true);
    }
  });
});

describe("hook execution from a subdirectory", () => {
  test("a post-edit hook still reaches Sentinel for the project when the session is in a subdirectory", async () => {
    const { result, invocations } = await launch(
      handlers("PostToolUse")[0],
      payload("PostToolUse", { tool_name: "Edit", tool_input: { file_path: join(fixture.root, "src/A.java") } }),
      join(fixture.root, "src/main/java"),
    );
    expect(invocations.map((i) => i.argv)).toEqual([
      ["hook", "claude-code", "--learn-after", "3", "--exclude-spec", "--event-stdin", "-C", fixture.root],
    ]);
    expect(result.exitCode).toBe(0);
  });

  test("the guard hook still reaches Sentinel for the project when the session is in a subdirectory", async () => {
    const { invocations } = await launch(
      handlers("PreToolUse")[0],
      payload("PreToolUse", { tool_name: "Read", tool_input: {} }),
      join(fixture.root, "src/main/java"),
    );
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "claude-code", "--guard-approved-specs", "--event-stdin", "-C", fixture.root]]);
  });
});

describe("Sentinel responses through the generated hooks", () => {
  test("a passing check after an edit exits 0", async () => {
    rmSync(join(fixture.root, "FAIL"), { force: true });
    const { result } = await launch(handlers("PostToolUse")[0], payload("PostToolUse", { tool_name: "Write", tool_input: { file_path: join(fixture.root, "src/A.java") } }), fixture.root);
    expect(result.exitCode).toBe(0);
  });

  test("a failing check exits 2 with the findings on stderr, which Claude Code shows to Claude", async () => {
    writeFileSync(join(fixture.root, "FAIL"), "");
    try {
      const { result } = await launch(handlers("PostToolUse")[0], payload("PostToolUse", { tool_name: "Edit", tool_input: { file_path: join(fixture.root, "src/A.java") } }), fixture.root);
      expect(result.exitCode).toBe(2);
      expect(result.stderr).toContain("format");
    } finally {
      rmSync(join(fixture.root, "FAIL"), { force: true });
    }
  });

  test("a protected spec edit is denied with a PreToolUse permission decision", async () => {
    const { result } = await launch(
      handlers("PreToolUse")[0],
      payload("PreToolUse", { tool_name: "Edit", tool_input: { file_path: join(fixture.root, "openspec/specs/auth/spec.md") } }),
      fixture.root,
    );
    expect(result.exitCode).toBe(0);
    const decision = JSON.parse(result.stdout);
    expect(decision.hookSpecificOutput).toMatchObject({ hookEventName: "PreToolUse", permissionDecision: "deny" });
    expect(String(decision.hookSpecificOutput.permissionDecisionReason).length).toBeGreaterThan(0);
  });

  test("an active-change edit and a read are left to Claude Code's own permissions", async () => {
    for (const input of [
      { tool_name: "Edit", tool_input: { file_path: join(fixture.root, "openspec/changes/add-x/tasks.md") } },
      { tool_name: "Read", tool_input: { file_path: join(fixture.root, "openspec/specs/auth/spec.md") } },
    ]) {
      const { result } = await launch(handlers("PreToolUse")[0], payload("PreToolUse", input), fixture.root);
      expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
    }
  });

  test("a protected shell command is denied", async () => {
    const { result } = await launch(
      handlers("PreToolUse")[0],
      payload("PreToolUse", { tool_name: "Bash", tool_input: { command: "rm openspec/specs/auth/spec.md" } }),
      fixture.root,
    );
    expect(JSON.parse(result.stdout).hookSpecificOutput.permissionDecision).toBe("deny");
  });

  test("a malformed guard payload is refused rather than allowed", async () => {
    const { result } = await launch(handlers("PreToolUse")[0], "{not json", fixture.root);
    expect(JSON.parse(result.stdout).hookSpecificOutput.permissionDecision).toBe("deny");
  });

  test("turn-end findings block the stop once, then reach only the user", async () => {
    writeFileSync(join(fixture.root, "SPEC_FAIL"), "");
    try {
      const first = await launch(handlers("Stop")[0], payload("Stop", { stop_hook_active: false }), fixture.root);
      expect(first.result.exitCode).toBe(0);
      const block = JSON.parse(first.result.stdout);
      expect(block.decision).toBe("block");
      expect(block.reason).toContain("missing scenario");
      const second = await launch(handlers("Stop")[0], payload("Stop", { stop_hook_active: true }), fixture.root);
      const message = JSON.parse(second.result.stdout);
      expect(message.decision).toBeUndefined();
      expect(message.systemMessage).toContain("missing scenario");
    } finally {
      rmSync(join(fixture.root, "SPEC_FAIL"), { force: true });
    }
  });

  test("a failure that recurs across three episodes produces learning context on the passing check", async () => {
    // Learning counts a recurring rule finding once per failing episode, after --learn-after 3. While FAIL
    // exists the stub mvnw writes a Checkstyle LineLength report, so the learned problem is that rule.
    const edit = () =>
      launch(handlers("PostToolUse")[0], payload("PostToolUse", { tool_name: "Edit", tool_input: { file_path: join(fixture.root, "src/A.java") } }), fixture.root);
    rmSync(join(fixture.root, ".sentinel"), { recursive: true, force: true });
    const passes = [];
    for (let episode = 0; episode < 3; episode++) {
      writeFileSync(join(fixture.root, "FAIL"), "");
      try {
        expect((await edit()).result.exitCode).toBe(2);
      } finally {
        rmSync(join(fixture.root, "FAIL"), { force: true });
      }
      passes.push(await edit());
    }
    expect(passes.map((p) => p.result.exitCode)).toEqual([0, 0, 0]);
    expect(passes[0].result.stdout.trim()).toBe("");
    const context = JSON.parse(passes[2].result.stdout).hookSpecificOutput;
    expect(context.hookEventName).toBe("PostToolUse");
    expect(String(context.additionalContext)).toContain("AGENTS.md");
    expect(String(context.additionalContext)).toContain("LineLength");
  });

  test("a clean turn end lets Claude stop", async () => {
    const { result } = await launch(handlers("Stop")[0], payload("Stop", { stop_hook_active: false }), fixture.root);
    expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
  });
});

describe("settings ownership", () => {
  test("a Sentinel hook path without ownership is a conflict and the file is preserved", async () => {
    const root = join(dirname(fixture.root), "conflict-project");
    rmSync(root, { recursive: true, force: true });
    mkdirSync(join(root, ".claude"), { recursive: true });
    writeFileSync(join(root, "pom.xml"), readFileSync(join(fixture.root, "pom.xml")));
    const text = JSON.stringify({ hooks: { Stop: [{ hooks: [{ type: "command", command: ".claude/hooks/sentinel-edit-write" }] }] } });
    writeFileSync(join(root, ".claude/settings.json"), text);
    const result = await run([...fixture.sentinel.argv, "integrate", "claude-code", "-C", root], { cwd: root, env: fixture.env, timeoutMs: 60_000 });
    expect(result.stdout).toContain("CONFLICT");
    expect(readFileSync(join(root, ".claude/settings.json"), "utf8")).toBe(text);
  });

  test("user hooks and permissions survive install, refresh and removal, and legacy entries are replaced", async () => {
    const root = join(dirname(fixture.root), "merge-project");
    rmSync(root, { recursive: true, force: true });
    mkdirSync(join(root, ".claude"), { recursive: true });
    writeFileSync(join(root, "pom.xml"), readFileSync(join(fixture.root, "pom.xml")));
    // A merged settings file from an earlier Sentinel: ownership marker plus a relative hook path.
    const user = {
      sentinelOwnership: "sentinel-owned: claude-code-edit-write v1",
      permissions: { allow: ["Bash(npm test)"] },
      hooks: {
        PreToolUse: [{ matcher: "Bash", hooks: [{ type: "command", command: "./user-hook.sh" }] }],
        PostToolUse: [{ matcher: "^(Edit|Write|MultiEdit)$", hooks: [{ type: "command", command: ".claude/hooks/sentinel-edit-write" }] }],
      },
    };
    writeFileSync(join(root, ".claude/settings.json"), JSON.stringify(user, null, 2));
    const sentinel = (args: string[]) => run([...fixture.sentinel.argv, ...args, "-C", root], { cwd: root, env: fixture.env, timeoutMs: 60_000 });
    expect((await sentinel(["integrate", "claude-code"])).exitCode).toBe(0);
    const merged = JSON.parse(readFileSync(join(root, ".claude/settings.json"), "utf8"));
    expect(merged.permissions).toEqual(user.permissions);
    expect(merged.hooks.PreToolUse).toContainEqual(user.hooks.PreToolUse[0]);
    const postCommands = merged.hooks.PostToolUse.flatMap((group: any) => group.hooks.map((h: any) => h.command));
    expect(postCommands).toEqual(["${CLAUDE_PROJECT_DIR}/.claude/hooks/sentinel-edit-write"]);
    expect((await sentinel(["integrate", "claude-code"])).exitCode).toBe(0);
    expect(JSON.parse(readFileSync(join(root, ".claude/settings.json"), "utf8"))).toEqual(merged);
    expect((await sentinel(["integrate", "claude-code", "--remove"])).exitCode).toBe(0);
    const removed = JSON.parse(readFileSync(join(root, ".claude/settings.json"), "utf8"));
    expect(removed.permissions).toEqual(user.permissions);
    expect(removed.hooks).toEqual({ PreToolUse: user.hooks.PreToolUse });
    expect(removed.sentinelOwnership).toBeUndefined();
  });
});

test("recorded invocations run in the project directory", () => {
  const recorded = recordedInvocations(log).filter((i) => i.argv.includes("-C"));
  expect(recorded.length).toBeGreaterThan(0);
  expect(recorded.every((i) => i.argv.at(-1) === fixture.root)).toBe(true);
  expect(realpathSync(fixture.root).length).toBeGreaterThan(0);
});
